"Loudness": "Loudness",
"The ceiling for the peaks between samples. −1 leaves room for the MP3 and AAC encoders, which add peaks of their own.": "Il tetto per i picchi tra i campioni. −1 lascia margine agli encoder MP3 e AAC, che aggiungono picchi propri.",
"Also an MP3 at 320 kbps, beside the WAV and the FLAC.": "Anche un MP3 a 320 kbps, accanto al WAV e al FLAC.",
"also MP3": "anche MP3",
"What is upscaled: the take, or any file made from it but an upscaled one.": "Cosa passa all'upscale: il take, o qualsiasi file ricavato da esso, tranne uno già passato all'upscale.",
"Mode": "Modalità",
"how deep it redraws": "quanto in profondità ridisegna",
"Subtle — above 12 kHz": "Sottile — sopra i 12 kHz",
"Normal — above 8 kHz": "Normale — sopra gli 8 kHz",
"High — above 6 kHz": "Alto — sopra i 6 kHz",
"Extreme — above 4 kHz": "Estremo — sopra i 4 kHz",
"How many versions to draw: they differ only by the noise, and each takes as long as the first. Two let you pick by ear.": "Quante versioni disegnare: differiscono solo per il rumore e ognuna richiede quanto la prima. Con due puoi scegliere a orecchio.",
"Variants": "Varianti",
"Keep the original below the cutoff": "Mantieni l'originale sotto il taglio",
"What is debuzzed: the take, or a file made from it that is neither debuzzed nor upscaled.": "Cosa passa all'antironzio: il take, o un file ricavato da esso che non sia già passato né all'antironzio né all'upscale.",
"Strength": "Intensità",
"How much of the frame ripple to divide out. Viktor's ear: 100 % thinned the opening, 80 % was right.": "Quanta ondulazione di trama togliere. L'orecchio di Viktor: 100 % ha assottigliato l'attacco, 80 % era giusto.",
"Which file is measured: the take, or any file made from it.": "Quale file si misura: il take, o qualsiasi file ricavato da esso.",
"Inspect": "Ispeziona",
"Where the sound sits: spectrogram, average spectrum, band energy. Lay another take over it to compare.": "Dove si colloca il suono: spettrogramma, spettro medio, energia per bande. Sovrapponi un altro take per confrontare.",
"Log": "Logaritmica",
"Linear": "Lineare",
"Lays a second spectrum under this one, on the same scale: a file made from this take, or another take.": "Mette un secondo spettro sotto questo, sulla stessa scala: un file ricavato da questo take, o un altro take.",
"Compare with": "Confronta con",
"Full screen: zoom and scroll (or double-click the picture). A click plays from there when this take is in the player.": "Schermo intero: zoom e scorrimento (o doppio clic sull'immagine). Un clic riproduce da lì quando questo take è nel lettore.",
"Full screen: zoom and scroll": "Schermo intero: zoom e scorrimento",
"Whisper listens to this take on Forge and matches what it hears to your lyrics, minute by minute.": "Whisper ascolta questo take su Forge e confronta ciò che sente con il tuo testo, minuto per minuto.",
"What Whisper listens to": "Cosa ascolta Whisper",
"The take as it is, or a stem of it: on the vocal stem Whisper hears the words without the music": "Il take così com'è, o un suo stem: sullo stem della voce Whisper sente le parole senza la musica",
"Listen with Whisper": "Ascolta con Whisper",
"Karaoke timing": "Tempi del karaoke",
"Time the lines": "Sincronizza le righe",
"Made from this take": "Nato da questo take",
