"The ticked ones, or with none ticked the whole trash: deleted for good, with everything made from them. Asks first.": "Quelli spuntati o, se non ne è spuntato nessuno, tutto il cestino: eliminati per sempre, con tutto ciò che ne è nato. Chiede prima.",
