"Hide": "Nascondi",
"Export format": "Formato di esportazione",
"FLAC: lossless, about half the size of WAV. WAV: for tools that take nothing else.": "FLAC: senza perdita, circa metà delle dimensioni del WAV. WAV: per gli strumenti che non accettano altro.",
"Also every file made from each take (remasters, stems, upscales, debuzzed files), named after the take.": "Anche ogni file nato da ciascun take (remaster, stem, upscale, file passati all'antironzio), con il nome del take.",
"with what is made from them": "con ciò che ne è nato",
"A ZIP made on Forge, then saved by the browser where you tell it": "Uno ZIP creato su Forge, poi salvato dal browser dove gli dici",
"Export ZIP": "Esporta ZIP",
"To the trash": "Nel cestino",
"The Librarian lives in Forge's lab, which does not answer: not found": "Il Bibliotecario vive nel laboratorio di Forge, che non risponde: non trovato",
"a LoRA for YuE2 from your own songs · the guide: LORA-TRAINING.md": "una LoRA per YuE2 dalle tue canzoni · la guida: LORA-TRAINING.md",
