"Search runs · set · kind": "Cerca esecuzioni · set · tipo",
"The server log, in every room: click to unfold or fold": "Il log del server, in ogni stanza: clic per espandere o comprimere",
"The line to the studio: the round trip, the middle of the last five (every 20 s). Near: the studio answers at once.": "La linea verso lo studio: andata e ritorno, la mediana delle ultime cinque (ogni 20 s). Vicino: lo studio risponde subito.",
"Follow: the log keeps to its newest line as the engine writes. Off: it stays where you scrolled to read.": "Segui: il log resta sulla riga più recente mentre il motore scrive. Spento: resta dove l'hai scorso per leggere.",
"The whole log, in Engine": "Il log completo, in Motore",
"Unfold the takes list": "Espandi l'elenco dei take",
