"≈ A guess: the painter does not know this instrument, and the critic did not find it in any of the pictures it drew.": "≈ Un'ipotesi: il pittore non conosce questo strumento, e il critico non l'ha trovato in nessuna delle immagini che ha disegnato.",
"⚠ A name in the style is a request, not a promise. What ▶ A and ▶ B play is what YuE2 gives for it, about nine times in ten. Some probes are superb, and A and B agree, yet the instrument is not the one asked for: trust the ear, not the name.": "⚠ Un nome nello stile è una richiesta, non una promessa. Ciò che suonano ▶ A e ▶ B è ciò che YuE2 dà per quel nome, circa nove volte su dieci. Alcune prove sono splendide, e A e B concordano, eppure lo strumento non è quello richiesto: fidati dell'orecchio, non del nome.",
