"How wide the adapter's change is: 16 for one voice or instrument, 32 for a style, 64 for many voices, 128 at most.": "Quanto ampiamente l'adattatore cambia i pesi: 16 per una voce o uno strumento, 32 per uno stile, 64 per molte voci, 128 al massimo.",
"Whether the music half learns (the part that writes the song's tokens), and how hard its lesson pulls against the anchor: 0 leaves it as the base, a timbre only; raise it for diction and style. What counts is the anchor's share of it, not its size.": "Se la metà musicale impara (quella che scrive i token della canzone) e quanto forte la sua lezione tira contro l'ancora: 0 la lascia com'è la base, solo un timbro; alzalo per la dizione e lo stile. Conta la quota dell'ancora rispetto a esso, non la sua grandezza.",
"Pulls the music half back toward the base model, so it keeps what the set does not show. Read it as a share of the AR weight: a tenth lets it move, as much as the weight holds it near the base. Nothing at AR weight 0.": "Tira la metà musicale indietro verso il modello di base, perché conservi ciò che il set non mostra. Leggila come una quota del Peso AR: un decimo la lascia muovere, quanto il peso la tiene vicino alla base. Con Peso AR 0 non fa nulla.",
"The music half's learning rate as a share of the one above: the knob that makes it learn faster or slower (0.5: half as fast). It learns a small set by heart quickly.": "Il learning rate della metà musicale come quota di quello sopra: la manopola che la fa imparare più in fretta o più piano (0.5: a metà). Un set piccolo lo impara presto a memoria.",
"How they work ›": "Come funzionano ›",
"The music half's three knobs: the guide": "Le tre manopole della metà musicale: nella guida",
