"two ways: the mixed track as it is, or the whole take into your DAW, where the rest happens outside the studio": "due strade: la traccia mixata così com'è, o l'intero take nella tua DAW, dove il resto avviene fuori dallo studio",
"The mixed track": "La traccia mixata",
"As the studio made it (and the Refiner finished it), no DAW in between.": "Così come l'ha fatta lo studio (e l'ha rifinita il Rifinitore), senza DAW in mezzo.",
"As the studio made it (and the Refiner finished it), no DAW in between. The take in hand:": "Così come l'ha fatta lo studio (e l'ha rifinita il Rifinitore), senza DAW in mezzo. Il take in mano:",
"Open a take, play one, or check one in the Librarian: its WAV, FLAC and MP3 come here.": "Apri un take, riproducine uno o spuntane uno nel Bibliotecario: il suo WAV, FLAC e MP3 compaiono qui.",
