"experimental": "sperimentale",
"It works and was checked, but it still needs crash tests on other machines and projects, and more work": "Funziona ed è stato verificato, ma servono ancora crash test su altre macchine e progetti, e altro lavoro",
"The whole take as a project of your DAW: the stems on their tracks, the score as MIDI, the tempo, the sections as regions, the lyrics on the timeline. Which DAW do you use?": "L'intero take come progetto della tua DAW: gli stem sulle loro tracce, la partitura come MIDI, il tempo, le sezioni come regioni, il testo sulla timeline. Quale DAW usi?",
