"first": "la prima",
"next": "la successiva",
"Now: the": "Ora:",
"project (the mix, every stem, the score as MIDI; the lyrics and sections once the take is timed in the Refiner’s lyrics check), and": "— progetto (il mix, ogni stem, la partitura come MIDI; il testo e le sezioni quando il take ha i tempi nella verifica del testo del Rifinitore), e",
"(the mix, every stem, the score as notes, the sections as markers: Waveform 14, Bitwig, Studio One, Cubase); both also in a take’s menu → Download. Waveform: 14 or newer.": "(il mix, ogni stem, la partitura come note, le sezioni come marcatori: Waveform 14, Bitwig, Studio One, Cubase); entrambi anche nel menu di un take → «Scarica». Waveform: 14 o successiva.",
"Packing…": "Impacchettamento…",
"60 days of evaluation with every function, then a licence: $60 for personal use or a small business": "60 giorni di prova con tutte le funzioni, poi una licenza: $60 per uso personale o una piccola impresa",
"Waveform Free 14 or newer: free, no track or export limits; it opens the studio's DAWproject (File > Import Other > Import a DAWproject file). Waveform 13 is not supported": "Waveform Free 14 o successiva: gratuita, senza limiti di tracce o esportazione; apre il DAWproject dello studio (File > Import Other > Import a DAWproject file). Waveform 13 non è supportata",
"30 days without limits after signing up, then Essentials $99, Producer $199 or Studio $399 (bitwig.com, 03.10.2026); opens the studio's DAWproject: the mix, the stems, the score as notes, the sections as markers": "30 giorni senza limiti dopo la registrazione, poi Essentials $99, Producer $199 o Studio $399 (bitwig.com, 03.10.2026); apre il DAWproject dello studio: il mix, gli stem, la partitura come note, le sezioni come marcatori",
"reaper.fm/download.php → the Linux x86_64 tarball → unpack it and run ./install-reaper.sh (it goes to /opt/REAPER)": "reaper.fm/download.php → il tarball Linux x86_64 → estrailo ed esegui ./install-reaper.sh (va in /opt/REAPER)",
