"⚠ {0}: {1} on the music half is past its limit {2}: the score tends to fail after 70-200 tokens.": "⚠ {0}: {1} sulla metà musicale supera il suo limite {2}: la partitura di solito cede dopo 70-200 token.",
"⚠ {0}: {1} on the sound half is past its limit {2}.": "⚠ {0}: {1} sulla metà sonora supera il suo limite {2}.",
