"The older official decoder. The published benchmark scores were made with it. Less clean than Standard; some hear it as more musical. Same encoder, only the decoder differs.": "Il decoder ufficiale precedente. I punteggi pubblicati dei benchmark sono stati ottenuti con esso. Meno pulito dello Standard; ad alcuni suona più musicale. Lo stesso encoder, cambia solo il decoder.",
"A community weight mix of the two official decoders: 2/3 Standard + 1/3 Legacy. Not newly trained. It sits between the clean Standard and the more musical Legacy; the real-audio LoRA's authors suggest it.": "Una miscela di pesi della comunità dei due decoder ufficiali: 2/3 Standard + 1/3 Precedente. Non riaddestrata. Sta tra lo Standard pulito e il Precedente più musicale; la consigliano gli autori della LoRA real-audio.",
