"Training may take GPU{0}, the studio’s own card: if it does, synthesis waits until the run ends (Engine → GPUs gives training another card).": "L'addestramento può occupare GPU{0}, la scheda propria dello studio: se lo fa, la sintesi aspetta che l'esecuzione finisca (Motore → GPU dà all'addestramento un'altra scheda).",
