"Training {0}": "Addestramento di {0}",
"Listener": "Ascoltatore",
"drafts each track’s style from what it hears; a draft, read and correct it": "abbozza lo stile di ogni traccia da ciò che sente; una bozza, leggila e correggila",
"Trigger": "Trigger",
"Shared line": "Riga comune",
"after the track’s tags": "dopo i tag della traccia",
"the album’s vibe": "l'atmosfera dell'album",
"Write into the captions": "Scrivi nelle didascalie",
"Listening… {0} / {1}": "Ascolto… {0} / {1}",
"Listen to {0}": "Ascolta {0}",
"Listen to {0}?": "Ascoltare {0}?",
"Omni hears 120 s of every track and drafts its style. Drafts heard before are kept aside (styles.DATE.json); the captions change only when you write them.": "Omni ascolta 120 s di ogni traccia e ne abbozza lo stile. Le bozze ascoltate prima vengono messe da parte (styles.DATE.json); le didascalie cambiano solo quando le scrivi.",
"Listen": "Ascolta",
"Listening to {0}": "Ascolto di {0}",
"Write {#0} styles into the captions of {1}?": "Scrivere {0} stili nelle didascalie di {1}?",
"Each first line becomes: {0} The lyrics stay.": "Ogni prima riga diventa: {0} Il testo resta.",
"Write": "Scrivi",
"{#0} captions written": {"one": "{0} didascalia scritta", "many": "{0} didascalie scritte", "other": "{0} didascalie scritte"},
"drafts here by {0}": "bozze qui di {0}",
"The studio’s trainer is missing {0}:": "All'addestratore dello studio manca {0}:",
"Comfy-Org's YuE2 {0} weights": "i pesi {0} di YuE2 di Comfy-Org",
"the realaudio tokenizer head": "la testa del tokenizer realaudio",
"and": "e",
"AI-Toolkit is not found at": "AI-Toolkit non si trova in",
": clone ostris/ai-toolkit there (or set AITK_ROOT for the lab), or train with the studio’s own trainer.": ": clona lì ostris/ai-toolkit (o imposta AITK_ROOT per il laboratorio), oppure addestra con l'addestratore dello studio.",
"The realaudio tokenizer is missing from": "Manca il tokenizer realaudio in",
"{#0} characters, about {#1} tokens.": "{0} caratteri, circa {1} token.",
"Style and lyrics together: about {#0} of {#1} tokens.": "Stile e testo insieme: circa {0} di {1} token.",
"Style and lyrics together: about {#0} of {#1} tokens — too long for a full-length song and score.": "Stile e testo insieme: circa {0} di {1} token — troppo lungo per una canzone completa con partitura.",
"Unlike the model's training styles:": "Non somiglia agli stili su cui è stato addestrato il modello:",
"longer than 1,600 characters (the official examples stop at 999)": "più di 1.600 caratteri (gli esempi ufficiali arrivano a 999)",
"{#0} Unicode arrow (→): write -> instead": "frecce Unicode (→): {0}: scrivi -> al loro posto",
"{#0} Unicode arrows (→): write -> instead": "frecce Unicode (→): {0}: scrivi -> al loro posto",
"dynamics marks (never in the official styles)": "segni di dinamica (mai negli stili ufficiali)",
"{#0} \"Label:\" fields (5 of 110 official styles use any)": "{0} campi «Label:» (5 dei 110 stili ufficiali ne usano)",
"{#0} bracket line in the lyrics with a \"Label:\", an arrow or a p/f mark (none in the official examples)": "righe tra parentesi nel testo con «Label:», una freccia o un segno p/f: {0} (nessuna negli esempi ufficiali)",
"{#0} bracket lines in the lyrics with a \"Label:\", an arrow or a p/f mark (none in the official examples)": "righe tra parentesi nel testo con «Label:», una freccia o un segno p/f: {0} (nessuna negli esempi ufficiali)",
"{#0} instruments": {"one": "{0} strumento", "many": "{0} strumenti", "other": "{0} strumenti"},
"{#0} heard": "ascoltati: {0}",
"{#0} questioned": "in dubbio: {0}",
"{#0} not identified": "non identificati: {0}",
"{#0} not judged yet": "non ancora valutati: {0}",
"the Librarian does not answer: no probes to play": "il Bibliotecario non risponde: nessuna prova da riprodurre",
"{#0} styles": {"one": "{0} stile", "many": "{0} stili", "other": "{0} stili"},
"{#0} style": {"one": "{0} stile", "many": "{0} stili", "other": "{0} stili"},
"what a probe gave instead of its instrument": "cosa ha dato una prova al posto del suo strumento",
"Nothing matches.": "Niente corrisponde.",
"⚠ A name in the style is a request, not a promise. What ▶ A and ▶ B play is what YuE2 gives for it, about nine times in ten.": "⚠ Un nome nello stile è una richiesta, non una promessa. Ciò che suonano ▶ A e ▶ B è ciò che YuE2 dà per quel nome, circa nove volte su dieci.",
"Some probes are superb, and A and B agree, yet the instrument is not the one asked for: trust the ear, not the name.": "Alcune prove sono splendide, e A e B concordano, eppure lo strumento non è quello richiesto: fidati dell'orecchio, non del nome.",
"What YuE2 was asked to play, one instrument or one style at a time, in probes of two minutes (one minute for the first ones), two seeds each, A and B.": "Cosa è stato chiesto di suonare a YuE2, uno strumento o uno stile alla volta, in prove di due minuti (un minuto le prime), due semi ciascuna, A e B.",
"An instrument shapes the style of the whole piece: naming one moves the arrangement too. A crackle or a rustle of paper, as on a worn record, is an unlucky seed: make it again on another.": "Uno strumento modella lo stile di tutto il brano: nominarlo sposta anche l'arrangiamento. Un crepitio o un fruscio di carta, come su un disco consumato, è un seme sfortunato: rifallo con un altro.",
