"A run is in progress; the next song is queued behind it.": "C'è un'esecuzione in corso; la prossima canzone è in coda dietro di essa.",
"Your note on this take, kept with it: saved as you type, and the same note in the Librarian.": "La tua nota su questo take, conservata con esso: si salva mentre scrivi, ed è la stessa nota che nel Bibliotecario.",
