"The studio's approved sets, as their author published them. Each comes in as a workspace of its own, locked against deletion: its takes as MP3 with their covers, titles and notes. Only what you ask for is downloaded.": "Le raccolte approvate dello studio, così come le ha pubblicate il loro autore. Ognuna arriva come uno spazio a sé, bloccato contro l'eliminazione: i suoi take in MP3 con copertine, titoli e note. Si scarica solo ciò che chiedi.",
