"“{0}” is here already": "«{0}» è già qui",
"Restoring brings back the copy published on Hugging Face: the takes it lacks come again, titles and notes return to the published ones, and what was added to it leaves the workspace (those takes stay in the library; its own sections stay). To keep yours as it is: Cancel, rename your workspace (the ⋯ beside its name, then Rename…), and Get again: the original comes in beside it under its own name.": "Il ripristino riporta la copia pubblicata su Hugging Face: i take che mancano tornano, titoli e note tornano a quelli pubblicati, e ciò che vi è stato aggiunto esce dallo spazio (quei take restano nella libreria; le sue sezioni restano).\n\nPer tenere il tuo così com'è: «Annulla», rinomina il tuo spazio (⋯ accanto al nome, poi «Rinomina…») e di nuovo «Prendi»: l'originale arriva accanto, con il suo nome.",
"Restore the original": "Ripristina l'originale",
