"Its takes stay as they are: they are heard and read, never changed, moved or thrown away, and they leave All Workspaces and the search (a take also in a workspace that is not frozen stays there). The workspace greys out; Unfreeze in its ⋯ menu brings everything back.": "I suoi take restano come sono: si ascoltano e si leggono, ma non si cambiano, non si spostano e non si buttano, ed escono da «Tutti gli spazi» e dalla ricerca (un take che sta anche in uno spazio non congelato resta lì). Lo spazio diventa grigio; «Scongela» nel suo menu ⋯ riporta tutto.",
