"Loading the Sound Heresy": "Caricamento dell'Eresia Sonora",
"Artwork for “{0}” already waits in the queue for a card": "La copertina di «{0}» aspetta già una GPU in coda",
"Artwork for “{0}” is being drawn already": "La copertina di «{0}» è già in disegno",
"Artwork for “{0}” waits in the queue for a card with room; it starts by itself (Engine → GPUs says which card does what)": "La copertina di «{0}» aspetta in coda una GPU con spazio e parte da sola (Motore → GPU dice cosa fa ogni scheda)",
"Artwork for “{0}” waits in the queue: {1}. It starts by itself when a card has room": "La copertina di «{0}» attende in coda: {1}. Partirà da sola quando una scheda avrà spazio",
"Artwork waits for a card…": "La copertina aspetta una GPU…",
"Drawing artwork…": "Si disegna la copertina…",
"Show disliked": "Mostra i Non mi piace",
"The disliked ones too": "Anche i Non mi piace",
"A dislike hides a take from the lists, as SUNO does; nothing is deleted. Ticked, the disliked show too; the 👎 chip shows only them": "Come in SUNO, «Non mi piace» nasconde un take dalle liste; non si cancella nulla. Spuntato, si vedono anche loro; il 👎 mostra solo quelli",
"“{0}” disliked: it leaves the lists; nothing is deleted (“Show disliked” brings it back)": "«{0}» non mi piace: esce dalle liste, non si cancella nulla («Mostra i Non mi piace» lo riporta)",
"Warning": "Attenzione",
"Characters: {#0} · tokens: ≈{#1} · with the lyrics: ≈{#2} of {#3}": "Caratteri: {0} · token: ≈{1} · con il testo: ≈{2} su {3}",
"What to expect: YuE2 learned from styles without these, and the engine hands the style over word for word. What the model never saw can come out sung as words, or pull the sound away from the style. Written as the official styles are, the style holds.": "Cosa aspettarsi: YuE2 ha imparato da stili senza questo, e il motore passa lo stile parola per parola. Ciò che il modello non ha mai visto può uscire cantato come parole o portare il suono lontano dallo stile. Scritto come gli stili ufficiali, lo stile tiene.",
"What to expect: the style, the lyrics, the score and the song share one window of 24,576 tokens; past the budget the score or the song is cut short.": "Cosa aspettarsi: lo stile, il testo, la partitura e la canzone condividono una finestra di 24.576 token; oltre il budget la partitura o la canzone si interrompono.",
"The score's and the song's token budgets alone fill the window of 24,576 tokens: nothing is left for the style and the lyrics. Lower max tokens under Score sampling or Music sampling, or Max length.": "I budget di token della partitura e della canzone riempiono da soli la finestra di 24.576 token: non resta nulla per lo stile e il testo. Abbassa max tokens in «Campionamento della partitura» o «Campionamento della musica», o la «Durata massima».",
"Only the liked": "Solo i Mi piace",
"Only the disliked: a dislike hides a take from the lists, as SUNO does (nothing is deleted); this shows them": "Solo i Non mi piace: «Non mi piace» nasconde un take dalle liste, come in SUNO (non si cancella nulla); questo pulsante li mostra",
"“{0}” disliked: it leaves the lists; nothing is deleted (the 👎 filter shows it)": "«{0}» non mi piace: esce dalle liste, non si cancella nulla (il filtro 👎 lo mostra)",
"Artwork": "Copertina",
"artwork": "copertina",
"Painter": "Pittore",
"Who paints a take's artwork: the player's, the cards', the MP3's cover. A drawing waits in the queue for a card with room.": "Chi dipinge la copertina di un take: per il lettore, le schede, l'MP3. Un disegno aspetta in coda una GPU con spazio.",
"Krea 2 Muse paints instruments and scenes far truer than SDXL (the studio's A/B on twelve instruments, 05.10.2026); SDXL is for cards it does not fit": "Krea 2 Muse dipinge strumenti e scene molto più fedeli di SDXL (l'A/B dello studio su dodici strumenti, 05.10.2026); SDXL è per le schede in cui non entra",
"By the cards: Krea 2 Muse Q4 from 16 GB, else SDXL": "In base alle GPU: Krea 2 Muse Q4 da 16 GB, altrimenti SDXL",
