"Together": "Insieme",
"All together": "Tutti insieme",
"All the adapters' strengths together: stacked, they add up, and past about {#0} the picture burns (its colours and edges overdone), however modest each one is. Green to {#1}, amber to {#2}, red past it. Drag it to move them all at once, each in proportion.": "Le forze di tutti gli adattatori insieme: sovrapposti si sommano, e oltre circa {#0} l'immagine brucia (colori e bordi esagerati), per quanto modesto sia ciascuno. Verde fino a {#1}, ambra fino a {#2}, rosso oltre. Trascinalo per muoverli tutti insieme, ognuno in proporzione.",
"none here for {0}": "nessuno qui per {0}",
"{#0} here": "qui: {#0}",
"Into the prompt:": "Nel prompt:",
"not in artwork/loras/ any more": "non è più in artwork/loras/",
"Four adapters at most: take one off first": "Quattro adattatori al massimo: togline prima uno",
"Already in the prompt: {0}": "Già nel prompt: {0}",
"Take it off": "Togli",
"Its strength": "La sua forza",
"The adapters for {0}": "Gli adattatori per {0}",
"LoRA for {0}": "LoRA per {0}",
"Search: name, words": "Cerca: nome, parole",
"Search": "Cerca",
"Look up on Civitai": "Cerca su Civitai",
"Each adapter not yet known looked up on civitai.com by its SHA-256 alone: its name, its base model and its trigger words kept beside it (NAME.civitai.info), with its first picture rated safe when it has none": "Ogni adattatore non ancora noto si cerca su civitai.com solo dal suo SHA-256: il nome, il modello base e le parole chiave restano accanto (NAME.civitai.info), con la sua prima immagine segnata come sicura quando non ne ha una",
