"On Civitai, pick adapters by their base model ({0}), download the .safetensors and put it there; Look up on Civitai then fills in its name and its trigger words.": "Su Civitai scegli gli adattatori dal loro modello base ({0}), scarica il .safetensors e mettilo lì; «Cerca su Civitai» poi ne completa il nome e le parole chiave."
