"compute {0} has no BF16 tensor cores: BF16 runs slower than Q8_0 here": "compute {0} non ha tensor core BF16: qui BF16 va più lento di Q8_0",
"{0} is not on this machine: Engine → Models and LoRAs fetches it": "{0} non è su questa macchina: «Motore → Modelli e LoRA» lo scarica",
