"The take in hand out of the studio: the mixed track as it is, or the whole take into your DAW (with its stems, once they are split here)": "Il take in mano fuori dallo studio: la traccia mixata così com'è, o il take intero nella tua DAW (con i suoi stem, una volta separati qui)",
"{#0} checked: a line with a number acts on all of them": "{#0} spuntati: una riga con un numero agisce su tutti",
"Text profiles make a pasted text ready to read: pick a Speech profile in Profile to use them": "I profili di testo preparano un testo incollato per la lettura: scegli un profilo Speech in Profilo per usarli",
