"{0} context": "contesto di {0}",
"Not in OpenRouter's list: check the name": "Non è nell'elenco di OpenRouter: controlla il nome",
"Any model of openrouter.ai/models, written provider/model; the field offers the whole list as you type, each with its price per million tokens in and out. The quick picks fill it in.": "Qualsiasi modello di openrouter.ai/models, scritto fornitore/modello; il campo offre l'intero elenco mentre scrivi, ciascuno con il suo prezzo per milione di token in entrata e in uscita. Le scelte rapide lo riempiono.",
