"Photos with JPEG compression; keeps the grain and the noise. The slowest here, and in full precision only.": "Foto con compressione JPEG; mantiene grana e rumore. Il più lento qui, e solo in precisione piena.",
"Degraded photos, faces too: a large model trained on blur, noise and compression. Slow, and the heaviest on the card.": "Foto degradate, anche volti: un modello grande addestrato su sfocatura, rumore e compressione. Lento, e il più pesante per la scheda.",
