"ClearReality's softer sister: kinder to rendered and game pictures, weaker on real photos. Quick. Non-commercial.": "La sorella più morbida di ClearReality: più gentile con render e immagini di giochi, più debole su foto vere. Veloce. Non commerciale.",
"Realistic photos with noise and compression. Quick.": "Foto realistiche con rumore e compressione. Veloce.",
