"General pictures with more detail and less smoothing: skin and fine texture do not turn mushy. Quick. Non-commercial. The third pass of Viktor's chain.": "Immagini generali con più dettaglio e meno levigatura: pelle e texture fine non diventano pappa. Veloce. Non commerciale. Il terzo passaggio della catena di Viktor.",
