"{#0} takes have these pictures as their covers: take the covers off them too, or leave them? Each take keeps a copy of its own.": { "one": "{#0} take ha queste immagini come copertina: toglierle anche da lì o lasciarle? Ogni take ne tiene una copia sua.", "other": "{#0} take hanno queste immagini come copertine: toglierle anche da lì o lasciarle? Ogni take ne tiene una copia sua." },
