RuachI18n.add("it", {
"Spectrum over the wave": "Spettro sopra l'onda",
"Spectrum over the wave: the pointer on the wave brings the whole take's spectrogram up over the player, as wide as the wave, the section's words above it. Click to turn it off.": "Spettro sopra l'onda: il puntatore sull'onda porta sopra il lettore lo spettrogramma dell'intero take, largo quanto l'onda, con le parole della sezione sopra. Clic per spegnerlo.",
"The take's spectrum": "Lo spettro del take",
"spectral centroid": "centroide spettrale",
"The spectral centroid: where the sound's weight sits at each moment, its brightness; higher is brighter": "Il centroide spettrale: dove sta il peso del suono in ogni momento, la sua brillantezza; più in alto, più brillante",
"RMS: how loud each moment is, in dBFS, in the lane at the foot; the dashed line is the take's own average": "RMS: quanto è forte ogni momento, in dBFS, nella fascia in basso; la linea tratteggiata è la media del take",
"Frequency scale": "Scala delle frequenze",
"The frequencies on a log scale, as the ear hears them: each octave as tall as the next": "Le frequenze in scala logaritmica, come le sente l'orecchio: ogni ottava alta quanto la successiva",
"The frequencies on a linear scale: the highs wide, the lows packed at the foot": "Le frequenze in scala lineare: gli acuti larghi, i bassi schiacciati in fondo",
"The mean power of each band over the whole take (Welch, dB): SUB 20–80 Hz, LOW 80–300, MID 300–2k, HI-MID 2–6k, HIGH 6–12k, AIR 12–20k": "La potenza media di ogni banda sull'intero take (Welch, dB): SUB 20–80 Hz, LOW 80–300, MID 300–2k, HI-MID 2–6k, HIGH 6–12k, AIR 12–20k",
"peak {0} dBFS": "picco {0} dBFS",
"RMS {0} dBFS": "RMS {0} dBFS",
"centroid {0}": "centroide {0}",
"loudest {0}": "la più forte {0}",
"here {0}": "qui {0}",
"{0} Hz": "{0} Hz",
"no spectrum in this page": "nessuno spettro in questa pagina"
});
// HERESY 1169 · 1375: the Artist's From the take; a run its painter left silent
RuachI18n.add("it", {
"From the take": "Dal take",
"its painter said nothing for {#0} minutes: stopped": { "one": "il suo pittore non ha detto nulla per {#0} minuto: fermato", "other": "il suo pittore non ha detto nulla per {#0} minuti: fermato" },
"its painter said nothing for {#0} s: stopped": "il suo pittore non ha detto nulla per {#0} s: fermato",
"A second pass, as Viktor's ComfyUI workflow makes it: the picture brought up 1.5 or 2 times and painted over by its own painter, adapters, prompt and seed, with the form's steps and sampler; a run of its own": "Un secondo passaggio, come lo fa il workflow ComfyUI di Viktor: l'immagine ingrandita 1.5 o 2 volte e ridipinta dal suo stesso pittore, adattatori, prompt e seme, con i passi e il campionatore del modulo; un'esecuzione a sé",
"Second pass…": "Secondo passaggio…",
"How much the second pass may change the picture: 0.3 keeps its drawing and adds detail, 0.5 sharpens its matter, 0.7 repaints its forms": "Quanto il secondo passaggio può cambiare l'immagine: 0.3 tiene il disegno e aggiunge dettaglio, 0.5 affina la materia, 0.7 ridipinge le forme",
"Second pass asked:": "Secondo passaggio chiesto:",
"The second pass ×{0} waits for a card with room, then paints the picture over": "Il secondo passaggio ×{0} aspetta una scheda con spazio, poi ridipinge l'immagine",
"No second pass: {0}": "Nessun secondo passaggio: {0}",
"second pass ×{0}": "secondo passaggio ×{0}",
"Extra noise": "Rumore aggiunto",
"Fresh noise added to the picture before it is painted from, as Viktor's ComfyUI workflow does (InjectLatentNoise): 0 none, 0.3 new grain and detail, 0.6 his second pass, above 1 the picture's forms begin to break": "Rumore fresco aggiunto all'immagine prima di dipingere da essa, come fa il workflow ComfyUI di Viktor (InjectLatentNoise): 0 nessuno, 0.3 grana e dettaglio nuovi, 0.6 il suo secondo passaggio, oltre 1 le forme dell'immagine cominciano a rompersi",
"extra noise {0}": "rumore aggiunto {0}",
"Regions": "Regioni",
"Up to three parts of the frame, each with words of its own: at every step the painter is asked once more for each region, with the prompt and the region's words, and the answers are blended by soft-edged boxes (Latent Couple's way). Each region costs a whole pass more a step. Krea 2 and Qwen-Image 2512": "Fino a tre parti dell'inquadratura, ognuna con parole sue: a ogni passo al pittore si chiede ancora una volta per ogni regione, con il prompt e le parole della regione, e le risposte si fondono per riquadri dal bordo morbido (alla maniera di Latent Couple). Ogni regione costa un passaggio intero in più a passo. Krea 2 e Qwen-Image 2512",
"Add a region": "Aggiungi una regione",
"Not with Qwen-Image 2.1: it edits by words": "Non con Qwen-Image 2.1: modifica con le parole",
"Where in the frame": "Dove nell'inquadratura",
"What is there": "Cosa c'è lì",
"Remove the region": "Togli la regione",
"Left half": "Metà sinistra",
"Right half": "Metà destra",
"Top half": "Metà superiore",
"Bottom half": "Metà inferiore",
"Left third": "Terzo sinistro",
"Middle third": "Terzo centrale",
"Right third": "Terzo destro",
"The middle": "Il centro",
"Top left": "In alto a sinistra",
"Top right": "In alto a destra",
"Bottom left": "In basso a sinistra",
"Bottom right": "In basso a destra",
"regions {0}": "regioni: {0}",
"About the regions": "Sulle regioni",
"Use it": "Usarla",
"to paint from": "per dipingere da essa",
"to edit by words (Qwen-Image 2.1)": "per modificarla con le parole (Qwen-Image 2.1)",
"for its style only (Qwen-Image 2.1)": "solo per il suo stile (Qwen-Image 2.1)",
"How the picture is used: painted from (image to image, by the form's painter, as far as How much it may change says); edited by the prompt's words (Qwen-Image 2.1 keeps the scene and changes what the words say); or for its style only (Qwen-Image 2.1 paints the prompt's own scene in the picture's technique, brushwork, palette and light). Qwen-Image 2.1 is under the Qwen Research Licence: research and evaluation only": "Come si usa l'immagine: dipingere da essa (image to image, con il pittore del modulo, fin dove dice Quanto può cambiare); modificarla con le parole del prompt (Qwen-Image 2.1 tiene la scena e cambia ciò che dicono le parole); o solo il suo stile (Qwen-Image 2.1 dipinge la scena del prompt con la tecnica, la pennellata, la tavolozza e la luce dell'immagine). Qwen-Image 2.1 è sotto la Qwen Research Licence: solo ricerca e valutazione",
"in the picture's style": "nello stile dell'immagine",
"edited by words": "modificata con le parole",
"The answer reached the output limit: review it carefully, or raise Max tokens.": "La risposta ha raggiunto il limite di uscita: controllala con cura o alza «Max token».",
"The model gave an empty answer: nothing came back from {0}.": "Il modello ha dato una risposta vuota: da {0} non è arrivato nulla.",
"It may have spent the whole answer on its thinking, or stopped at once. Send it again, raise Max tokens, or pick another model.": "Forse ha speso tutta la risposta nel ragionare, o si è fermato subito. Invialo di nuovo, alza «Max token» o scegli un altro modello.",
"The writer failed: {0}": "Lo Scrittore non è riuscito: {0}",
"Lettering": "Scritta",
"About the lettering": "Sulla scritta",
"A title, and a second line under it, lettered as part of the painting, not laid over it: Qwen-Image paints them with the picture, or Qwen-Image 2.1 letters a finished one, the reference. Each picture is read back by the listener (Qwen2.5-Omni) and one misspelled is painted again with another seed, up to three times; one still misspelled is said so, with what it reads": "Un titolo, e una seconda riga sotto, scritti come parte del dipinto, non sovrapposti: Qwen-Image li dipinge con l'immagine, oppure Qwen-Image 2.1 scrive su una già finita, il riferimento. L'ascoltatore (Qwen2.5-Omni) rilegge ogni immagine, e quella con un errore viene dipinta di nuovo con un altro seme, fino a tre volte; se l'errore resta, viene detto, con ciò che si legge",
"The words to letter, exactly as they are to be spelled": "Le parole della scritta, esattamente come vanno scritte",
"The take's title": "Il titolo della ripresa",
"The title of the take picked on the right": "Il titolo della ripresa scelta a destra",
"Second line": "Seconda riga",
"Smaller, under the title: the artist, the album; empty for none": "Più piccola, sotto il titolo: l'artista, l'album; vuota per nessuna",
"The letters": "Le lettere",
"large elegant classical serif capitals in warm gold, with even letter spacing": "grandi ed eleganti maiuscole classiche con grazie, in oro caldo, con spaziatura uniforme",
"What the letters look like, in words: the kind of letters, their colour, how they sit; empty: classical serif capitals in warm gold": "Come sono le lettere, a parole: il tipo, il colore, come stanno; vuoto: maiuscole classiche con grazie in oro caldo",
"At the top": "In alto",
"In the middle": "Al centro",
"At the bottom": "In basso",
"How": "Come",
"Painted with the picture: Qwen-Image 2512 or 2.1 paints the prompt's scene and the letters in it. On the reference: Qwen-Image 2.1 letters the reference picture by words and keeps the rest": "Dipinta con l'immagine: Qwen-Image 2512 o 2.1 dipinge la scena del prompt e le lettere al suo interno. Sul riferimento: Qwen-Image 2.1 scrive sull'immagine di riferimento con le parole e conserva il resto",
"painted with the picture": "dipinta con l'immagine",
"on the reference picture (Qwen-Image 2.1)": "sul riferimento (Qwen-Image 2.1)",
"Lettering a finished picture is Qwen-Image 2.1's: it is not on this machine": "Scrivere su un'immagine finita spetta a Qwen-Image 2.1, che non è su questa macchina",
"On the reference picture: take one with «As reference» first": "Sul riferimento: prendi prima un'immagine con «Come riferimento»",
"Lettering is Qwen-Image's: choose Qwen-Image 2512 or 2.1 as the painter": "La scritta la fa Qwen-Image: scegli Qwen-Image 2512 o 2.1 come pittore",
"Lettering on this picture: write its title, then Draw (Qwen-Image 2.1 letters it and keeps the rest)": "Scritta su questa immagine: scrivi il titolo, poi «Disegna» (Qwen-Image 2.1 la scrive e conserva il resto)",
"Spelled as asked: the listener reads it so": "Scritto come richiesto: l'ascoltatore lo legge così",
"Misspelled in every try: it reads": "Errore in ogni tentativo: si legge",
"tries": "tentativi",
"lettered": "scritta",
"misspelled: it reads": "con errore: si legge",
"Letter this picture: the title and second line of the form's Lettering, by Qwen-Image 2.1, the rest kept": "Scrivi su questa immagine: il titolo e la seconda riga della «Scritta» del modulo, con Qwen-Image 2.1, il resto resta",
"Letter it": "Scrivi",
"Not read back:": "Non riletto:",
"Where in the frame the lettering stands: across its upper part, its middle or its lower part": "Dove sta la scritta nell'inquadratura: nella parte alta, al centro o nella parte bassa",
"Lyrics guidance": "Guida del testo",
"as Guidance": "come la Guida",
"The lyrics' own guidance in the music stage: how hard the words are followed, apart from the style's pull, which Guidance keeps. Empty: the same as Guidance, as before. Viktor's measure: the lyrics below 2.6, while the music holds up to 4. A scale of its own adds a third branch, the prompt without its lyrics: a little more memory, about the same time": "La guida propria del testo nella fase della musica: quanto si seguono le parole, a parte la spinta dello stile, che tiene la Guida. Vuoto: come la Guida, come prima. La misura di Viktor: il testo sotto 2.6, mentre la musica regge fino a 4. Una scala propria aggiunge un terzo ramo, il prompt senza testo: un po' più di memoria, quasi lo stesso tempo",
"Viktor's measure: the lyrics hold below 2.6 while the music goes up to 4. Empty: the same as Guidance.": "La misura di Viktor: il testo regge sotto 2.6, mentre la musica arriva a 4. Vuoto: come il CFG.",
"Lyrics guidance from 2.6 is an experiment": "Il CFG del testo da 2.6 è un esperimento",
"Viktor's measure: the lyrics hold below 2.6, while the music (Guidance) is stable up to 4.": "La misura di Viktor: il testo regge sotto 2.6, mentre la musica (CFG) è stabile fino a 4.",
"Lyrics guidance must be a number, 0 or more": "La Guida del testo deve essere un numero, 0 o più",
"Repetition": "Ripetizione",
"Tokens": "Token",
"Time": "Tempo",
"Seconds of music": "Secondi di musica",
"Length cap": "Limite di durata",
"Sound stage": "Fase del suono",
"Decoder": "Decodificatore",
"Whole run": "Tutta l'esecuzione",
"Realtime": "Tempo reale",
"Versions × variations": "Versioni × variazioni",
"Score guard": "Guardiano della partitura",
"Free tempo": "Tempo libero",
"Free tempo: the music is made from the score without its tempo marks (Q:), so the voice and the beat breathe on their own: rubato, non-linear. The score in the form keeps them; Direct has no score to free. On by itself when the Style asks for rubato or non-linear and names no BPM.": "Tempo libero: la musica si fa dalla partitura senza i suoi segni di tempo (Q:), così voce e ritmo respirano da soli: rubato, non lineare. La partitura nel modulo li conserva; Direct non ha partitura. Si accende da solo quando lo Stile chiede rubato o non-linear e non nomina BPM.",
"Want non-linearity or rubato? Remove the BPM from your style!": "Vuoi non linearità o rubato? Togli il BPM dal tuo stile!",
"Free tempo on: your Style asks for rubato or non-linear, so the music is made without the score's tempo": "Tempo libero acceso: il tuo Stile chiede rubato o non lineare, e la musica si fa senza il tempo della partitura",
"The run": "L'esecuzione",
"no score": "senza partitura",
"Within Viktor's range for the music, 1.0 to 4.0: 4.0 the brightest, 3.0 just as bright, 1.6 the studio's own": "Nell'intervallo di Viktor per la musica, da 1.0 a 4.0: 4.0 il più brillante, 3.0 quasi uguale, 1.6 quello dello studio",
"Past 4.0: brighter still, and the music may begin to break; listen before you keep it": "Oltre 4.0: ancora più brillante, e la musica può cominciare a rompersi; ascolta prima di tenerla",
"Far past Viktor's range for the music (1.0 to 4.0): expect a broken take": "Molto oltre l'intervallo di Viktor per la musica (1.0–4.0): aspettati una ripresa rotta",
"Within Viktor's range for the lyrics, 1.0 to 2.6: 2.2 holds the words with the music at 4.0; at 1.6 they dissolve, velvety": "Nell'intervallo di Viktor per il testo, da 1.0 a 2.6: 2.2 tiene le parole con la musica a 4.0; a 1.6 si sciolgono, vellutate",
"Past 2.6: the words begin to burn": "Oltre 2.6: le parole cominciano a bruciarsi",
"Far past 2.6: burnt words": "Molto oltre 2.6: parole bruciate",
"The lyrics follow Guidance here: past 2.6 they begin to burn; give them their own Lyrics guidance (2.2 holds them with the music at 4.0)": "Qui il testo segue la Guida: oltre 2.6 comincia a bruciarsi; dagli una sua Guida del testo (2.2 lo tiene con la musica a 4.0)",
"Viktor's range: the music 1.0 to 4.0; past it the light beside the field turns amber, then red": "L'intervallo di Viktor: la musica da 1.0 a 4.0; oltre, la luce accanto al campo diventa ambra, poi rossa",
"Viktor's range: the lyrics 1.0 to 2.6; past it the light beside the field turns amber, then red. Empty: the same as Guidance": "L'intervallo di Viktor: il testo da 1.0 a 2.6; oltre, la luce diventa ambra, poi rossa. Vuoto: come la Guida",
"The two guidances should differ: by 0.1 at the least, by 0.4 to 1.0 at best (Viktor's ear); equal, half the lyrics drift into hallucination, and the vowels lose their stress": "Le due guide devono differire: almeno di 0.1, meglio di 0.4–1.0 (l'orecchio di Viktor); uguali, metà del testo scivola nell'allucinazione e le vocali perdono l'accento",
"(Krea 2 Community License: its pictures pass a content filter); Times on an RTX 3090, the prompt and the look-over not counted.": "(Krea 2 Community License: le sue immagini passano un filtro dei contenuti); Tempi su una RTX 3090, senza il prompt e la revisione.",
"(Krea 2 Community License: its pictures pass a content filter); Qwen-Image 2512 (Apache-2.0) paints a cover with Lightning (lightx2v, Apache-2.0) when its file is here; Qwen-Image 2.1 is under Qwen's research licence: research and evaluation only, not for a song that is sold. Times on an RTX 3090, the prompt and the look-over not counted.": "(Krea 2 Community License: le sue immagini passano un filtro dei contenuti); Qwen-Image 2512 (Apache-2.0) dipinge una copertina con Lightning (lightx2v, Apache-2.0) quando il suo file è qui; Qwen-Image 2.1 è sotto la licenza di ricerca di Qwen: solo ricerca e valutazione, non per una canzone che si vende. Tempi su una RTX 3090, senza contare il prompt e la revisione.",
"By the cards: Qwen-Image 2512 where a card the lab's jobs may take holds it whole (it follows the prompt best and letters a title), else Krea 2 Muse, streamed from RAM on a small card. Measured on an RTX 3090 (13.10.2026), the prompt writer and the critic included: Krea 2 Muse Q4 about 65 s a cover, Qwen-Image 2512 Q4 125 s, Q6 131 s": "In base alle schede: Qwen-Image 2512 dove una scheda dei lavori del laboratorio lo contiene intero (segue meglio il prompt e scrive un titolo), altrimenti Krea 2 Muse, dalla RAM su una scheda piccola. Misurato su una RTX 3090 (13.10.2026), con l'autore del prompt e il critico: Krea 2 Muse Q4 circa 65 s a copertina, Qwen-Image 2512 Q4 125 s, Q6 131 s",
"By the cards: Qwen-Image 2512 where a card holds it whole (Q6 from 20 GB, Q4 from 16 GB), else Krea 2 Muse Q4": "In base alle schede: Qwen-Image 2512 dove una scheda lo contiene intero (Q6 da 20 GB, Q4 da 16 GB), altrimenti Krea 2 Muse Q4",
"Sections to sing anew": "Sezioni da cantare di nuovo",
"Hide disliked": "Nascondi i non graditi",
"the ☰ menu's own: the decoder for the songs to come": "lo stesso del menu ☰: il decodificatore per le prossime canzoni",
"Colour": "Colore",
"vinyl": "vinile",
"tape": "nastro",
"room": "stanza",
"A layer of sound under the song, laid in before the loudness: a record's surface with its fine crackle, a click now and then and the player's rumble; a tape's hiss; or the air of a room. The noise is new on every run.": "Uno strato di suono sotto la canzone, posato prima del volume: la superficie di un disco col suo crepitio fine, un clic ogni tanto e il rombo del giradischi; il soffio di un nastro; o l'aria di una stanza. Il rumore è nuovo a ogni passata.",
"Under the song, dB": "Sotto la canzone, dB",
"How far under the song's loudness the layer lies, in dB: −36 is heard in the quiet places, −50 barely, −20 plainly.": "Quanto sotto il volume della canzone sta lo strato, in dB: −36 si sente nei passaggi quieti, −50 appena, −20 chiaramente.",
"Qwen-Image 2512 Q6 by the cards (about 20 GB at its peak, the text encoder gone from the card by then)": "Qwen-Image 2512 Q6 secondo le schede (circa 20 GB al picco, il codificatore del testo già fuori dalla scheda)",
"Qwen-Image 2512 Q4 by the cards (about 15 GB at its peak, the text encoder gone from the card by then)": "Qwen-Image 2512 Q4 secondo le schede (circa 15 GB al picco, il codificatore del testo già fuori dalla scheda)",
"Krea painter": "Pittore Krea",
"31 GB fetched, its text encoder (16.6 GB) among it: the encoder reads the prompt and leaves the card, then the painter takes about 15 GB; for a card of 16 GB (below 20 GB the encoder reads on the processor: 17 GB of RAM); about two minutes a cover on a 3090; less when some of it is here": "31 GB da scaricare, tra cui il codificatore del testo (16,6 GB): il codificatore legge il prompt e lascia la scheda, poi il pittore occupa circa 15 GB; per una scheda da 16 GB (sotto i 20 GB il codificatore legge sul processore: 17 GB di RAM); circa due minuti a copertina su una 3090; meno se una parte è già qui",
"its text encoder among it, gone from the card before the painter comes: the painter takes about 20 GB, for a card of 20 GB; less when some of it is here": "tra cui il codificatore del testo, che lascia la scheda prima che arrivi il pittore: il pittore occupa circa 20 GB, per una scheda da 20 GB; meno se una parte è già qui",
"Copy the cover to its namesakes…": "Copia la copertina negli omonimi…",
"the takes of the same name": "le prese con lo stesso nome",
"Copy the cover of “{0}” to its namesakes?": "Copiare la copertina di «{0}» negli omonimi?",
"has a cover of its own": "ha una copertina sua",
"A cover replaced is kept beside its take, in artwork-removed/.": "Una copertina sostituita resta accanto alla sua presa, in artwork-removed/.",
"Replace theirs too": "Sostituire anche le loro",
"Only the ones without": "Solo a quelle senza",
"The cover copied to {0} of its namesakes": "Copertina copiata negli omonimi: {0}",
"No namesake took the cover": "Nessun omonimo ha preso la copertina",
"Voices (not a section: the lines stay in the section before; Viktor's form: sung or said, who, then how after a dash; no Solo)": "Voci (non sono una sezione: le righe restano nella sezione prima; la forma di Viktor: cantata o detta, chi, dopo un trattino come; senza Solo)",
"A woman sings the lines that follow, until another voice is named; after the dash how she sings: Deep, Warm; Soft, Breathy.": "Una donna canta le righe che seguono, finché non si nomina un'altra voce; dopo il trattino come canta: Deep, Warm; Soft, Breathy.",
"A man sings the lines that follow; after the dash how he sings: Bari-tenor, Calm; Low, Raspy.": "Un uomo canta le righe che seguono; dopo il trattino come canta: Bari-tenor, Calm; Low, Raspy.",
"A woman says the lines that follow instead of singing them; after the dash how: Soft Whisper, Intimate, Sacred.": "Una donna dice le righe che seguono invece di cantarle; dopo il trattino come: Soft Whisper, Intimate, Sacred.",
"A man says the line instead of singing it; after the dash how: Soft Whisper; Calm.": "Un uomo dice la riga invece di cantarla; dopo il trattino come: Soft Whisper; Calm.",
"Heard on a long ballad (written there «Female Voice - …»): a narrator's whisper between sung verses.": "Sentito in una lunga ballata (scritto lì «Female Voice - …»): il sussurro di una narratrice tra strofe cantate.",
"A spoken tag may lead the line itself: «[Spoken: Female - Soft Whisper] Ты слышишь?».": "Un tag parlato può aprire la riga stessa: «[Spoken: Female - Soft Whisper] Ты слышишь?».",
"A section and its voice: a deep female voice takes the chorus (heard on a long ballad; «Solo» in it is not heard)": "Una sezione e la sua voce: una voce femminile profonda prende il ritornello (sentito in una lunga ballata; «Solo» non si sente)",
"a stress mark after a vowel: обе́щано, сули́т (holds in about 90 % of lines; the rest is the seed's luck)": "un segno d'accento dopo una vocale: обе́щано, сули́т (tiene in circa il 90 % delle righe; il resto è fortuna del seme)",
"a capital stressed vowel with its mark pushes the stress where the rhyme wants it: базилиО́; a capital alone (дрОв) seldom moves it": "una vocale tonica maiuscola col suo segno spinge l'accento dove lo vuole la rima: базилиО́; una maiuscola da sola (дрОв) di rado lo sposta",
"round brackets are no command: a word or two in the lyrics' language is mostly sung as a choir's echo; a direction in them is mostly passed by, or sung": "le parentesi tonde non sono un comando: una o due parole nella lingua del testo si cantano per lo più come eco di coro; un'indicazione dentro per lo più viene saltata, o cantata",
"not a section": "non è una sezione",
"heard": "sentito",
"Not a section: who sings and how; the lines stay in the section before": "Non è una sezione: chi canta e come; le righe restano nella sezione prima",
"Heard by Viktor's ear, not counted in the official examples": "Sentito dall'orecchio di Viktor, non contato negli esempi ufficiali",
"Not a section: who sings and how; the lines stay in the section before. Viktor's form; on a long ballad YuE2 followed such tags about 95 % of the time. «Solo» is not heard in a voice's tag: name the voice.": "Non è una sezione: chi canta e come; le righe restano nella sezione prima. La forma di Viktor; su una lunga ballata YuE2 ha seguito questi tag circa il 95 % delle volte. «Solo» non si sente in un tag di voce: nomina la voce.",
"Made from it": "Fatto a partire da essa",
"Seen and kept": "Vedere e tenere",
"The Artist's brushes": "I pennelli dell'Artista",
"Every brush the Artist has here, in one list: Qwen-Image 2512 from a 4- or 6-bit GGUF; each fp8 file in artwork/Qwen-Image-2512/checkpoints/, 2512's own BASE and the fine-tunes (a file put there shows here when the room reads the list again); Qwen-Image 2.1. ⚡ Lightning: it paints in 8 steps by default; a fine-tune paints its finished realism without it unless Sampling asks": "Tutti i pennelli dell'Artista qui, in un elenco: Qwen-Image 2512 da un GGUF a 4 o 6 bit; ogni file fp8 in artwork/Qwen-Image-2512/checkpoints/, il BASE di 2512 e i fine-tune (un file messo lì compare qui quando la stanza rilegge l'elenco); Qwen-Image 2.1. ⚡ Lightning: dipinge in 8 passi di default; un fine-tune dipinge il suo realismo rifinito senza, a meno che il Campionamento non lo chieda",
"fine-tune": "fine-tune",
"research licence": "licenza di ricerca",
"Rooms": "Stanze",
"the rooms' names in the bar": "i nomi delle stanze nella barra",
"The font for the rooms' names in the bar. The text's own by default; a heading font makes them stand out.": "Il font dei nomi delle stanze nella barra. Quello del testo di default; un font dei titoli li fa risaltare.",
"Its note": "La sua nota",
"A note of your own on this picture: what it was made for, the words that lettered it, what to try next": "Una nota tua su questa immagine: a cosa serviva, le parole della scritta, cosa provare dopo",
"A note on the picture": "Una nota sull'immagine",
"Kept with the picture in its run: what it was made for, the words that lettered it, what to try next. Ctrl+Enter keeps it; an empty note takes it off.": "Resta con l'immagine nel suo giro: a cosa serviva, le parole della scritta, cosa provare dopo. Ctrl+Invio la tiene; una nota vuota la toglie.",
"Keep": "Tieni",
"Your note": "La tua nota",
"The note is kept with the picture": "La nota resta con l'immagine",
"The note is taken off": "Nota tolta",
"No note": "Nessuna nota",
"By the cards: Qwen-Image 2512 Q6 or Q4 where a card the lab's jobs may take holds it whole (it follows the prompt best and letters a title), else Q4 streamed from RAM on a smaller card. Measured on an RTX 3090 (14.10.2026), the prompt writer and the critic included: Q4 about 105 s a cover, its fp8 BASE about 95 s": "In base alle schede: Qwen-Image 2512 Q6 o Q4 dove una scheda che i lavori del laboratorio possono prendere lo contiene intero (segue meglio il prompt e scrive un titolo), altrimenti Q4 dalla RAM su una scheda più piccola. Misurato su una RTX 3090 (14.10.2026), con chi scrive il prompt e il critico: Q4 circa 105 s a copertina, il suo fp8 BASE circa 95 s",
"By the cards: Qwen-Image 2512 where a card holds it whole (Q6 from 20 GB, Q4 from 16 GB), else Q4 streamed from RAM": "In base alle schede: Qwen-Image 2512 dove una scheda lo contiene intero (Q6 da 20 GB, Q4 da 16 GB), altrimenti Q4 dalla RAM",
"Qwen-Image 2512 (Apache-2.0) paints a cover with Lightning (lightx2v, Apache-2.0) when its file is here, and every picture passes a content filter; Qwen-Image 2.1 is under Qwen's research licence: research and evaluation only, not for a song that is sold. Times on an RTX 3090, the prompt and the look-over not counted.": "Qwen-Image 2512 (Apache-2.0) dipinge una copertina con Lightning (lightx2v, Apache-2.0) quando il suo file è qui, e ogni immagine passa un filtro dei contenuti; Qwen-Image 2.1 è sotto la licenza di ricerca di Qwen: solo ricerca e valutazione, non per una canzone che si vende. Tempi su una RTX 3090, senza il prompt e la revisione.",
"Artwork: Qwen-Image 2512, by Qwen": "Copertine: Qwen-Image 2512, di Qwen",
"Artwork: Qwen-Image 2512 Lightning, by lightx2v": "Copertine: Qwen-Image 2512 Lightning, di lightx2v",
"pictures for your songs from a prompt of your own: square, wide and tall from one seed, painted by Qwen-Image": "immagini per le tue canzoni da un prompt tuo: quadrata, larga e alta da un solo seme, dipinte da Qwen-Image",
"How many steps from the noise to the picture: Qwen-Image 2512 with Lightning 4 to 16 (8 its own), 2512 without it and Qwen-Image 2.1 10 to 60": "Quanti passi dal rumore all'immagine: Qwen-Image 2512 con Lightning da 4 a 16 (8 i suoi), 2512 senza e Qwen-Image 2.1 da 10 a 60",
"artwork: no painter fits on this machine yet (Qwen-Image 2512 Q4 wants a card of 6 GB, streamed from 32 GB of RAM)": "copertine: nessun pittore entra ancora su questa macchina (Qwen-Image 2512 Q4 vuole una scheda da 6 GB, da 32 GB di RAM)",
"Each picture is about two minutes on a GPU (Qwen-Image 2512 with Lightning, the prompt and the look-over included): some {#0} minutes in all, drawn one after another; the studio stays yours meanwhile.": "Ogni immagine è circa due minuti su una GPU (Qwen-Image 2512 con Lightning, prompt e revisione compresi): circa {#0} minuti in tutto, una dopo l'altra; lo studio resta tuo nel frattempo.",
"Qwen-Image 2512 · Q4 · Lightning · about 15 GB · about 105 s a picture": "Qwen-Image 2512 · Q4 · Lightning · circa 15 GB · circa 105 s a immagine",
"Qwen-Image 2512 · {0} · Lightning · about 22 GB · about 95 s a picture": "Qwen-Image 2512 · {0} · Lightning · circa 22 GB · circa 95 s a immagine",
"Qwen-Image 2512 in fp8 from artwork/Qwen-Image-2512/checkpoints/ (ComfyUI's single files): 2512's own BASE file paints with Lightning, a fine-tune its finished realism without it unless asked; a card of 24 GB": "Qwen-Image 2512 in fp8 da artwork/Qwen-Image-2512/checkpoints/ (file singoli di ComfyUI): il file BASE di 2512 dipinge con Lightning, un fine-tune il suo realismo rifinito senza, se non richiesto; una scheda da 24 GB",
"Covers' helpers": "Aiutanti delle copertine",
"the prompt writer (Qwen3-4B-Instruct-2507, Apache-2.0) that writes a picture's prompt from the song, and the content filter (Falconsai/nsfw_image_detection, Apache-2.0) every picture passes; the painters are the Qwen ones below": "chi scrive il prompt (Qwen3-4B-Instruct-2507, Apache-2.0) di un'immagine dalla canzone, e il filtro dei contenuti (Falconsai/nsfw_image_detection, Apache-2.0) che ogni immagine passa; i pittori sono i Qwen qui sotto",
"the prompt writer and the filter": "chi scrive il prompt e il filtro",
"four adapters": "quattro adattatori",
"adapters for the Artist's painters, from {0}, shared there by their authors' leave (Civitai: share and sell): Lenovo UltraReal and Frank Frazetta for Qwen-Image 2.1; Film Photography and Photostyle by Sean Archer for 2512": "adattatori per i pittori dell'Artista, da {0}, condivisi lì con il permesso dei loro autori (Civitai: condividere e vendere): Lenovo UltraReal e Frank Frazetta per Qwen-Image 2.1; Film Photography e Photostyle by Sean Archer per 2512",
"Security": "Sicurezza",
"About security": "Sulla sicurezza",
"Who may open this studio: its page and everything it can do, your songs and lyrics, its jobs on your cards, its downloads with your keys. Kept on the studio's own computer (user/access.json) and in force at once.": "Chi può aprire questo studio: la sua pagina e tutto ciò che sa fare, le tue canzoni e i testi, i suoi lavori sulle tue schede, i suoi download con le tue chiavi. Si tiene sul computer dello studio stesso (user/access.json) e vale subito.",
"Asking the engine…": "Chiedo al motore…",
"This computer only": "Solo questo computer",
"the safest: no other machine can open it, not even your phone": "il più sicuro: nessun'altra macchina può aprirlo, nemmeno il tuo telefono",
"This computer and private networks": "Questo computer e le reti private",
"your home or office network, a VPN or Tailscale; a café's, a hotel's or a train's Wi-Fi is a private network too": "la rete di casa o dell'ufficio, una VPN o Tailscale; il Wi-Fi di un bar, di un albergo o di un treno è anch'esso una rete privata",
"This computer and the networks I list": "Questo computer e le reti che elenco",
"only the networks you trust, written as 10.0.0.0/24, a comma between them": "solo le reti di cui ti fidi, scritte come 10.0.0.0/24, separate da virgole",
"You open it from {0}: this computer": "Lo apri da {0}: questo computer",
"You open it from {0}: a private network": "Lo apri da {0}: una rete privata",
"You open it from {0}": "Lo apri da {0}",
"Who may open the studio": "Chi può aprire lo studio",
"The networks I list": "Le reti che elenco",
"Add the network you open it from now: {0}": "Aggiungi la rete da cui lo apri ora: {0}",
"the studio answers this computer only": "lo studio risponde solo a questo computer",
"the studio answers this computer and {0} listed networks": "lo studio risponde a questo computer e alle reti elencate ({0})",
"the studio answers this computer and private networks": "lo studio risponde a questo computer e alle reti private",
"This closes the studio to you": "Questo ti chiude lo studio",
"You open it from {0}, which the new choice leaves out: the page stops answering here, and only the studio's own computer can open it again (Engine → Security there, or delete user/access.json). Close it anyway?": "Lo apri da {0}, che la nuova scelta lascia fuori: la pagina qui smette di rispondere, e solo il computer dello studio stesso può riaprirlo (lì Motore → Sicurezza, o cancella user/access.json). Chiuderlo comunque?",
"Close it to me": "Chiudilo per me",
"The engine does not answer about its access: build it again (./build.sh --server).": "Il motore non risponde sul suo accesso: ricompilalo (./build.sh --server).",
"decided {0}": "deciso il {0}",
"RUACH_ALLOW_PUBLIC=1 is set: the studio answers anyone, whatever is chosen here.": "RUACH_ALLOW_PUBLIC=1 è impostato: lo studio risponde a chiunque, qualunque cosa si scelga qui.",
"This engine keeps no settings file, so it answers this computer and private networks; start it with ./start.sh to choose.": "Questo motore non tiene un file di impostazioni, quindi risponde a questo computer e alle reti private; avvialo con ./start.sh per scegliere.",
"Kept: {0}": "Tenuto: {0}",
"Not kept: {0}": "Non tenuto: {0}",
"Who may open this studio?": "Chi può aprire questo studio?",
"The studio listens on port {0} of every network this computer is on. Whoever opens its page can do everything you can: make and delete songs, read your lyrics, run your graphics cards, fetch models with your keys.": "Lo studio ascolta sulla porta {0} di ogni rete in cui si trova questo computer. Chi apre la sua pagina può fare tutto ciò che fai tu: creare e cancellare canzoni, leggere i tuoi testi, far lavorare le tue schede grafiche, scaricare modelli con le tue chiavi.",
"At home behind your router, private networks are what you want: your laptop and phone reach the studio, the internet does not.": "A casa, dietro il tuo router, le reti private sono ciò che vuoi: il portatile e il telefono raggiungono lo studio, internet no.",
"On a public Wi-Fi (a café, a hotel, a train) or on a laptop without a firewall, everyone on that network counts as a private network too: choose This computer only, or list your own networks.": "Su un Wi-Fi pubblico (un bar, un albergo, un treno) o su un portatile senza firewall, chiunque su quella rete conta anch'esso come rete privata: scegli «Solo questo computer» o elenca le tue reti.",
"Engine → Security changes it any time. The internet at large is never let in, unless the studio is started with RUACH_ALLOW_PUBLIC=1.": "Motore → Sicurezza lo cambia quando vuoi. Internet in generale non entra mai, a meno che lo studio non sia avviato con RUACH_ALLOW_PUBLIC=1.",
"My decision is a conscious one": "La mia decisione è consapevole",
"Batch": "Lotto",
"How many pictures in one go: each the next seed (the seed, the seed + 1, …), in every shape picked": "Quante immagini in una volta: ognuna il seme successivo (il seme, il seme + 1, …), in ogni forma scelta",
"Delete the saved style picked": "Elimina lo stile salvato scelto",
"Keep the list open": "Tieni la lista aperta",
"Play this song": "Riproduci questa canzone",
"My songs": "Le mie canzoni",
"“{0}” takes no new takes (a 💎 set, its section or a frozen workspace). Where do the new takes land?": "«{0}» non accetta nuove registrazioni (un set 💎, una sua sezione o uno spazio congelato). Dove finiscono le nuove registrazioni?",
"Nothing sent: the Librarian (Forge's lab) does not answer, so a new take would land in no workspace": "Niente inviato: il Bibliotecario (il laboratorio di Forge) non risponde, quindi una nuova registrazione non finirebbe in nessuno spazio",
"Nothing sent: the library is not on this page to say where the new takes land": "Niente inviato: la libreria non è in questa pagina per dire dove finiscono le nuove registrazioni",
"The song's arc and its verses' numbers. Press to go to the next one.": "L'arco della canzone e i numeri delle strofe. Premi per andare al prossimo.",
"Arc to look at: {0}": "Arco: {0}",
"an Intro after the song has begun": "un Intro a canzone già iniziata",
"{0} after the Outro ({1})": "{0} dopo l'Outro ({1})",
"an unnumbered Verse among numbered ones": "un Verse senza numero tra quelli numerati",
"Verse {0} after an unnumbered Verse": "Verse {0} dopo un Verse senza numero",
"Verse {0} again": "Verse {0} di nuovo",
"Verse {0} after Verse {1}": "Verse {0} dopo Verse {1}",
"Verse {0} after Verse {1}: Verse {2} is missing": "Verse {0} dopo Verse {1}: manca Verse {2}",
"the first Verse is Verse {0}": "la prima strofa è Verse {0}",
"{0} after {1}: the arc goes Verse › Pre-Chorus › Chorus › Post-Chorus (a section may be left out, not turned back)": "{0} dopo {1}: l'arco va Verse › Pre-Chorus › Chorus › Post-Chorus (una sezione può mancare, non tornare indietro)",
"Letters other than Latin in the Style: {0}. YuE2 reads the style as English tags: write it in Latin letters.": "Lettere non latine nello Stile: {0}. YuE2 legge lo stile come tag in inglese: scrivilo in lettere latine.",
"Style suggestions: the Writer's model reads the Style, the Title and the lyrics whole and offers short tags this song has not got yet; a click on one puts it in (before the BPM at its end)": "Suggerimenti di stile: il modello dello Scrittore legge lo Stile, il Titolo e il testo intero e offre tag brevi che la canzone non ha ancora; un clic su uno lo inserisce (prima del BPM in fondo)",
"Section marks": "Segni delle sezioni",
"the sections' names on the wave": "i nomi delle sezioni sull'onda",
"Buttons": "Pulsanti",
"every button with words, the toggles, the menus' items": "ogni pulsante con parole, gli interruttori, le voci dei menu",
"IBM Plex Mono, as they were (default)": "IBM Plex Mono, come prima (predefinito)",
"Its size against the text": "La sua dimensione rispetto al testo",
"The font of the sections' names drawn on the wave and on its scope; IBM Plex Mono, as they were, by default": "Il carattere dei nomi delle sezioni sull'onda e sulla sua vista; predefinito IBM Plex Mono, come prima",
"The font of every button with words, the toggles and the menus' items; the text's by default": "Il carattere di ogni pulsante con parole, degli interruttori e delle voci dei menu; predefinito quello del testo",
"Nothing to choose here yet": "Qui non c'è ancora nulla da scegliere",
"A song from the Writer": "Una canzone dallo Scrittore",
"Its title, style and lyrics into this form; it stays in hand, so the takes made from it are linked to it.": "Titolo, stile e testo in questo modulo; resta in mano, così le registrazioni fatte da essa le sono collegate.",
"A profile": "Un profilo",
"It sets every knob but the texts and the seeds; Apply puts it in the form.": "Imposta ogni manopola tranne i testi e i semi; Applica lo mette nel modulo.",
"A saved style": "Uno stile salvato",
"It goes into the Style box (asked first when something is there).": "Va nella casella Stile (chiede prima se c'è qualcosa).",
"A text profile": "Un profilo di testo",
"Its rules and its shape make a pasted text ready to be sung or read; Apply puts them to the lyrics.": "Le sue regole e la sua forma preparano un testo incollato per essere cantato o letto; Applica le mette al testo.",
"Turbo": "Turbo",
"Turbo: Qwen-Image 2.1 in 4 to 16 steps with its «Turbo 4step» adapter (AiMetatron's), for drafts; off: 30 steps, as 2.1 paints": "Turbo: Qwen-Image 2.1 in 4–16 passi con l'adattatore «Turbo 4step» (di AiMetatron), per le bozze; spento: 30 passi, come dipinge 2.1",
"Outpaint…": "Estendi i bordi…",
"Paint its edges on: the picture whole on a wider, taller or square canvas, the rest painted on by Qwen-Image 2.1 with the «Outpaint v2» adapter; the picture kept pixel for pixel": "Estendere i bordi: l'immagine intera su una tela più larga, più alta o quadrata, il resto lo dipinge Qwen-Image 2.1 con l'adattatore «Outpaint v2»; l'immagine resta identica pixel per pixel",
"Outpaint: its new shape": "Estendi i bordi: la nuova forma",
"The picture stays whole and as it is; Qwen-Image 2.1 paints the rest of the new canvas around it.": "L'immagine resta intera e com'è; Qwen-Image 2.1 dipinge intorno il resto della nuova tela.",
"square": "quadrato",
"wide": "largo",
"tall": "alto",
"What lies beyond its edges?": "Cosa c'è oltre i bordi?",
"A few words of the scene, if you want them (empty: Qwen-Image 2.1 reads the picture alone).": "Qualche parola sulla scena, se vuoi (vuoto: Qwen-Image 2.1 legge solo l'immagine).",
"Outpaint": "Estendi",
"a stormy sea, more of the cliff…": "un mare in tempesta, più scogliera…",
"Outpaint asked:": "Estensione richiesta:",
"No outpaint: ": "Nessuna estensione: ",
"No outpaint:": "Nessuna estensione:",
"Outpainting waits for a card with room, then paints the edges on": "L'estensione aspetta una scheda libera, poi dipinge i bordi",
"Outpainting is Qwen-Image 2.1's with its «Outpaint v2» adapter: it is not on this machine": "Estendere è di Qwen-Image 2.1 con l'adattatore «Outpaint v2»: non è su questa macchina"
});
